package edu.pe.cibertec.saibm.usuario.domain.model; import java.time.Instant; import java.util.UUID; public record UserProfile(UUID id,String firstName,String lastName,String dni,String email,AccountStatus status,Instant createdAt,Instant updatedAt,String legacyUserId){public UserProfile{if(id==null||firstName==null||firstName.isBlank()||lastName==null||lastName.isBlank()||dni==null||!dni.matches("[0-9]{4,20}")||email==null||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Invalid user profile");firstName=firstName.trim();lastName=lastName.trim();email=email.trim().toLowerCase(java.util.Locale.ROOT);status=status==null?AccountStatus.ACTIVE:status;createdAt=createdAt==null?Instant.now():createdAt;updatedAt=updatedAt==null?createdAt:updatedAt;}public static UserProfile create(UUID id,String first,String last,String dni,String email,String legacy,Instant at){return new UserProfile(id,first,last,dni,email,AccountStatus.ACTIVE,at,at,legacy);}public UserProfile update(String first,String last,String dni,String email,Instant at){return new UserProfile(id,first,last,dni,email,status,createdAt,at,legacyUserId);}public UserProfile deactivate(Instant at){return new UserProfile(id,firstName,lastName,dni,email,AccountStatus.DEACTIVATED,createdAt,at,legacyUserId);}public UserProfile reactivate(Instant at){return new UserProfile(id,firstName,lastName,dni,email,AccountStatus.ACTIVE,createdAt,at,legacyUserId);}public boolean active(){return status==AccountStatus.ACTIVE;}}
